import collections
import json
import statistics as s
from pathlib import Path
import sys


def analyze(data, labels):
    cells = collections.defaultdict(lambda: collections.defaultdict(list))
    for run in data['runs']:
        cells[run['case'], run['concurrency']][run['engine']].append(run)
    result = {'completed': 'completed_at' in data, 'windows': len(data['runs']),
              'requests': sum(r['requests'] for r in data['runs']),
              'errors': sum(r['errors'] for r in data['runs']), 'cells': []}
    for (case, concurrency), programs in cells.items():
        cell = {'case': case, 'concurrency': concurrency, 'programs': {}}
        for slot, runs in programs.items():
            record = {'samples': len(runs), 'errors': sum(r['errors'] for r in runs)}
            for metric, gate in [('rps', 10), ('p99_ms', 20)]:
                values = [r[metric] for r in runs]
                rounds = collections.defaultdict(list)
                for r in runs:
                    rounds[r['round']].append(r[metric])
                pairs = [200 * abs(v[0] - v[1]) / sum(v) for _, v in sorted(rounds.items()) if len(v) == 2]
                cv = 100 * s.stdev(values) / s.mean(values) if len(values) > 1 else None
                record[metric] = {'median': s.median(values), 'min': min(values), 'max': max(values),
                    'cv_percent': cv, 'aa_symmetric_differences_percent': pairs,
                    'gate_pass': len(values) == 6 and len(pairs) == 3 and max(pairs) <= gate
                    and cv <= gate and not record['errors']}
            for metric in ['p50_ms', 'p95_ms', 'server_cpu_us_per_request', 'peak_pss_kib']:
                record[metric + '_median'] = s.median(r[metric] for r in runs)
            cell['programs'][labels[slot]] = record
        if all(slot in programs for slot in ['rgnix', 'candidate']):
            a, b = [cell['programs'][labels[slot]] for slot in ['rgnix', 'candidate']]
            cell['candidate_rps_change_percent'] = 100 * (b['rps']['median'] / a['rps']['median'] - 1)
            cell['candidate_p99_change_percent'] = 100 * (b['p99_ms']['median'] / a['p99_ms']['median'] - 1)
            cell['throughput_gate_pass'] = a['rps']['gate_pass'] and b['rps']['gate_pass']
            cell['p99_gate_pass'] = a['p99_ms']['gate_pass'] and b['p99_ms']['gate_pass']
            cell['rounds'] = []
            for round_id in sorted({r['round'] for rs in programs.values() for r in rs}):
                pair = {e: [r for r in rs if r['round'] == round_id] for e, rs in programs.items()}
                if all(len(rs) == 2 for rs in pair.values()):
                    cell['rounds'].append({'round': round_id,
                        'candidate_rps_change_percent': 100 * (s.mean(r['rps'] for r in pair['candidate']) / s.mean(r['rps'] for r in pair['rgnix']) - 1),
                        'candidate_p99_change_percent': 100 * (s.mean(r['p99_ms'] for r in pair['candidate']) / s.mean(r['p99_ms'] for r in pair['rgnix']) - 1)})
        result['cells'].append(cell)
    return result


if __name__ == '__main__':
    print(json.dumps(analyze(json.loads(Path(sys.argv[1]).read_text()),
                             {'rgnix': sys.argv[2], 'candidate': sys.argv[3]}), indent=2))
